from datetime import date, timedelta

# Days a patron may keep each kind of item.
LOAN_DAYS = {
    "novel": 14,
    "magazine": 7,
    "dvd": 7,
    "tool": 5,
    "reference": 3,
}


def due_date(kind: str, checked_out: date) -> date:
    """The date an item of this kind must come back."""
    return checked_out + timedelta(days=LOAN_DAYS[kind])

import unittest
from datetime import date

from loans import due_date


class DueDateTest(unittest.TestCase):
    def test_novel(self):
        self.assertEqual(due_date("novel", date(2026, 3, 2)), date(2026, 3, 16))

    def test_dvd(self):
        self.assertEqual(due_date("dvd", date(2026, 3, 2)), date(2026, 3, 9))


if __name__ == "__main__":
    unittest.main()
